class TestNarrate(unittest.TestCase):
    def test_main_runs(self):
        """Test that main() runs without error with args."""
        with patch.object(sys, "argv", ["narrate.py", "book.epub"]):
            try:
                narrate.main()
            except Exception as e:
                self.fail(f"main() raised {type(e).__name__}: {e}")

    def test_main_exits_no_args(self):
        """Test that main() exits with code 2 when no args given."""
        with patch.object(sys, "argv", ["narrate.py"]):
            with self.assertRaises(SystemExit) as cm:
                narrate.main()
            self.assertEqual(cm.exception.code, 2)

    def test_logger_exists(self):
        """Test that module logger is configured."""
        self.assertIsNotNone(narrate.logger)
        self.assertEqual(narrate.logger.name, "narrate")
